def lastNonEmptyString(s: str) -> str:
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    max_count = max(counts.values())
    seen = set()
    result = []

    for ch in reversed(s):
        if counts[ch] == max_count and ch not in seen:
            seen.add(ch)
            result.append(ch)

    return ''.join(reversed(result))
