def smallestString(s: str) -> str:
    chars = list(s)
    n = len(chars)

    # Find the first character that is not 'a'
    i = 0
    while i < n and chars[i] == 'a':
        i += 1

    # If all characters are 'a', we must perform the operation,
    # so decrement the entire string (last 'a' becomes 'z')
    if i == n:
        chars[-1] = 'z'
        return ''.join(chars)

    # Decrement the contiguous run of non-'a' characters starting at i
    while i < n and chars[i] != 'a':
        chars[i] = chr(ord(chars[i]) - 1)
        i += 1

    return ''.join(chars)
