def numberOfRightTriangles(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Count number of 1s in each row and each column
    row_count = [sum(grid[i]) for i in range(rows)]
    col_count = [0] * cols
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                col_count[j] += 1

    total = 0
    # For each cell that is 1, it can serve as the right-angle corner.
    # The other two points must be in the same row and same column.
    # Number of choices: (row_count[i] - 1) * (col_count[j] - 1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                total += (row_count[i] - 1) * (col_count[j] - 1)

    return total
