import sys

class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.size = [1] * (n + 1)

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)

    operations = []
    for _ in range(M):
        K = next(it)
        C = next(it)
        vertices = [next(it) for _ in range(K)]
        operations.append((C, vertices))

    operations.sort(key=lambda x: x[0])

    dsu = DSU(N)
    answer = 0

    for C, vertices in operations:
        base = vertices[0]
        for v in vertices[1:]:
            if dsu.union(base, v):
                answer += C

    root = dsu.find(1)
    for v in range(2, N + 1):
        if dsu.find(v) != root:
            print(-1)
            return

    print(answer)

if __name__ == "__main__":
    solve()
```

