import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    H = int(data[0])
    W = int(data[1])
    S = data[2:2 + H]

    DOT = ord('.')
    HASH = ord('#')

    safe = [bytearray(W) for _ in range(H)]

    for i in range(H):
        row = S[i]
        for j in range(W):
            if row[j] != DOT:
                continue

            ok = True
            if i > 0 and S[i - 1][j] == HASH:
                ok = False
            elif i + 1 < H and S[i + 1][j] == HASH:
                ok = False
            elif j > 0 and row[j - 1] == HASH:
                ok = False
            elif j + 1 < W and row[j + 1] == HASH:
                ok = False

            if ok:
                safe[i][j] = 1

    visited = [bytearray(W) for _ in range(H)]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    ans = 1

    for i in range(H):
        for j in range(W):
            if safe[i][j] and not visited[i][j]:
                stack = [(i, j)]
                visited[i][j] = 1
                size = 0
                boundary = set()

                while stack:
                    x, y = stack.pop()
                    size += 1

                    for dx, dy in dirs:
                        nx = x + dx
                        ny = y + dy

                        if 0 <= nx < H and 0 <= ny < W and S[nx][ny] == DOT:
                            if safe[nx][ny]:
                                if not visited[nx][ny]:
                                    visited[nx][ny] = 1
                                    stack.append((nx, ny))
                            else:
                                boundary.add(nx * W + ny)

                total = size + len(boundary)
                if total > ans:
                    ans = total

    print(ans)

solve()
