import sys

def generate_placements(piece):
    cells = []
    for r in range(4):
        for c in range(4):
            if piece[r][c] == '#':
                cells.append((r, c))

    orientations = set()
    cur = cells

    for _ in range(4):
        min_r = min(r for r, c in cur)
        min_c = min(c for r, c in cur)
        norm = frozenset((r - min_r, c - min_c) for r, c in cur)
        orientations.add(norm)

        # Rotate 90 degrees clockwise inside a 4x4 grid
        cur = [(c, 3 - r) for r, c in cur]

    placements = set()

    for shape in orientations:
        max_r = max(r for r, c in shape)
        max_c = max(c for r, c in shape)

        for dr in range(4 - max_r):
            for dc in range(4 - max_c):
                mask = 0
                for r, c in shape:
                    rr = r + dr
                    cc = c + dc
                    mask |= 1 << (rr * 4 + cc)
                placements.add(mask)

    return placements


def solve():
    tokens = sys.stdin.read().split()
    if len(tokens) < 12:
        return

    pieces = [tokens[i * 4:(i + 1) * 4] for i in range(3)]

    areas = [sum(row.count('#') for row in piece) for piece in pieces]
    if sum(areas) != 16:
        print("No")
        return

    p1 = generate_placements(pieces[0])
    p2 = generate_placements(pieces[1])
    p3 = generate_placements(pieces[2])

    full = (1 << 16) - 1

    for m1 in p1:
        for m2 in p2:
            if m1 & m2:
                continue
            for m3 in p3:
                if (m1 & m3) == 0 and (m2 & m3) == 0:
                    if (m1 | m2 | m3) == full:
                        print("Yes")
                        return

    print("No")


if __name__ == "__main__":
    solve()
