def countBeautifulNumbers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_upto(n: int) -> int:
        if n <= 0:
            return 0

        digits = list(map(int, str(n)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool, diff: int, mod: int) -> int:
            if pos == length:
                return 1 if started and diff == 0 and mod == 0 else 0

            limit = digits[pos] if tight else 9
            total = 0

            for d in range(limit + 1):
                next_tight = tight and (d == limit)

                if not started and d == 0:
                    total += dp(pos + 1, next_tight, False, diff, mod)
                else:
                    next_diff = diff + (1 if d % 2 == 0 else -1)
                    next_mod = (mod * 10 + d) % k
                    total += dp(pos + 1, next_tight, True, next_diff, next_mod)

            return total

        return dp(0, True, False, 0, 0)

    return count_upto(high) - count_upto(low - 1)
