MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    H = int(data[0])
    W = int(data[1])
    grid = ''.join(data[2:2 + H])
    N = H * W

    mark = [0] * N
    cid = 0
    total_boundary = 0
    red_count = 0

    for i in range(N):
        ch = grid[i]
        if ch == '.':
            red_count += 1
        elif mark[i] == 0:
            cid += 1
            mark[i] = cid
            stack = [i]

            while stack:
                v = stack.pop()

                if v >= W:
                    u = v - W
                    if grid[u] == '#':
                        if mark[u] == 0:
                            mark[u] = cid
                            stack.append(u)
                    else:
                        if mark[u] != cid:
                            mark[u] = cid
                            total_boundary += 1

                if v < N - W:
                    u = v + W
                    if grid[u] == '#':
                        if mark[u] == 0:
                            mark[u] = cid
                            stack.append(u)
                    else:
                        if mark[u] != cid:
                            mark[u] = cid
                            total_boundary += 1

                c = v % W

                if c != 0:
                    u = v - 1
                    if grid[u] == '#':
                        if mark[u] == 0:
                            mark[u] = cid
                            stack.append(u)
                    else:
                        if mark[u] != cid:
                            mark[u] = cid
                            total_boundary += 1

                if c != W - 1:
                    u = v + 1
                    if grid[u] == '#':
                        if mark[u] == 0:
                            mark[u] = cid
                            stack.append(u)
                    else:
                        if mark[u] != cid:
