import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.read().split()))
    A = [data[i * 3:(i + 1) * 3] for i in range(3)]
    flat = [A[i][j] for i in range(3) for j in range(3)]

    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6)
    ]

    @lru_cache(maxsize=None)
    def takahashi_wins(board, turn):
        for a, b, c in lines:
            if board[a] == board[b] == board[c] == 1:
                return True
            if board[a] == board[b] == board[c] == 2:
                return False

        if 0 not in board:
            diff = 0
            for i, cell in enumerate(board):
                if cell == 1:
                    diff += flat[i]
                elif cell == 2:
                    diff -= flat[i]
            return diff > 0

        if turn == 0:
            for i, cell in enumerate(board):
                if cell == 0:
                    nb = list(board)
                    nb[i] = 1
                    if takahashi_wins(tuple(nb), 1):
                        return True
            return False
        else:
            for i, cell in enumerate(board):
                if cell == 0:
                    nb = list(board)
                    nb[i] = 2
                    if not takahashi_wins(tuple(nb), 0):
                        return False
            return True

    print("Takahashi" if takahashi_wins((0,) * 9, 0) else "Aoki")

if __name__ == "__main__":
    main()
