from typing import List

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0

        for i in range(n):
            seen = [False] * (n + 2)
            distinct = 0
            consecutive_pairs = 0

            for j in range(i, n):
                x = nums[j]

                if not seen[x]:
                    seen[x] = True
                    distinct += 1

                    if seen[x - 1]:
                        consecutive_pairs += 1
                    if seen[x + 1]:
                        consecutive_pairs += 1

                ans += distinct - 1 - consecutive_pairs

        return ans
