def minimumDistance(points):
    n = len(points)
    u = [x + y for x, y in points]
    v = [x - y for x, y in points]

    def get_stats(arr):
        max1 = max2 = -10**30
        min1 = min2 = 10**30
        cnt_max = cnt_min = 0

        for val in arr:
            if val > max1:
                max2 = max1
                max1 = val
                cnt_max = 1
            elif val == max1:
                cnt_max += 1
            elif val > max2:
                max2 = val

            if val < min1:
                min2 = min1
                min1 = val
                cnt_min = 1
            elif val == min1:
                cnt_min += 1
            elif val < min2:
                min2 = val

        return max1, max2, cnt_max, min1, min2, cnt_min

    u_max, u_max2, u_cnt_max, u_min, u_min2, u_cnt_min = get_stats(u)
    v_max, v_max2, v_cnt_max, v_min, v_min2, v_cnt_min = get_stats(v)

    ans = 10**30

    for i in range(n):
        if u_cnt_max == 1 and u[i] == u_max:
            u_hi = u_max2
        else:
            u_hi = u_max

        if u_cnt_min == 1 and u[i] == u_min:
            u_lo = u_min2
        else:
            u_lo = u_min

        r1 = u_hi - u_lo

        if v_cnt_max == 1 and v[i] == v_max:
            v_hi = v_max2
        else:
            v_hi = v_max

        if v_cnt_min == 1 and v[i] == v_min:
            v_lo = v_min2
        else:
            v_lo = v_min

        r2 = v_hi - v_lo
        d = r1 if r1 > r2 else r2

        if d < ans:
            ans = d

