def countSubarrays(nums):
    from collections import deque

    left = 0
    ans = 0
    max_q = deque()
    min_q = deque()

    for right, x in enumerate(nums):
        while max_q and nums[max_q[-1]] <= x:
            max_q.pop()
        max_q.append(right)

        while min_q and nums[min_q[-1]] >= x:
            min_q.pop()
        min_q.append(right)

        while nums[max_q[0]] - nums[min_q[0]] > 2:
            left += 1
            while max_q and max_q[0] < left:
                max_q.popleft()
            while min_q and min_q[0] < left:
                min_q.popleft()

        ans += right - left + 1

    return ans
