def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = 10**9

    divisors = [[] for _ in range(n + 1)]
    for length in range(2, n + 1):
        for d in range(1, length):
            if length % d == 0:
                divisors[length].append(d)

    cost = [[INF] * (n + 1) for _ in range(n + 1)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length
            best = INF

            for d in divisors[length]:
                group_len = length // d
                changes = 0

                for r in range(d):
                    for a in range(group_len // 2):
                        left = i + r + a * d
                        right = i + r + (group_len - 1 - a) * d
                        if s[left] != s[right]:
                            changes += 1

                if changes < best:
                    best = changes
                    if best == 0:
                        break

            cost[i][j] = best

    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for parts in range(1, k + 1):
        for end in range(2 * parts, n + 1):
            best = INF
            for start in range(2 * (parts - 1), end - 1):
                candidate = dp[parts - 1][start] + cost[start][end]
                if candidate < best:
                    best = candidate
            dp[parts][end] = best

    return dp[k][n]
