def maximizeTheProfit(n, offers):
    dp = [0] * n
    offers_by_end = [[] for _ in range(n)]

    for start, end, gold in offers:
        offers_by_end[end].append((start, gold))

    for i in range(n):
        if i > 0:
            dp[i] = dp[i - 1]

        for start, gold in offers_by_end[i]:
            previous = dp[start - 1] if start > 0 else 0
            dp[i] = max(dp[i], previous + gold)

