def incremovableSubarrayCount(nums):
    n = len(nums)
    count = 0

    def is_strictly_increasing(arr):
        for i in range(len(arr) - 1):
            if arr[i] >= arr[i + 1]:
                return False
        return True

    for i in range(n):
        for j in range(i, n):
            # Remove subarray nums[i..j]
            new_arr = nums[:i] + nums[j + 1:]
            if is_strictly_increasing(new_arr):
                count += 1

    return count
