def countServers(n, logs, x, queries):
    from collections import defaultdict

    times_by_server = defaultdict(list)
    for sid, t in logs:
        times_by_server[sid].append(t)

    max_q = max(queries)
    diff = [0] * (max_q + 2)

    for times in times_by_server.values():
        times.sort()
        cur_L = cur_R = None

        for t in times:
            L = t
            R = t + x

            if cur_L is None:
                cur_L, cur_R = L, R
            elif L <= cur_R:
                if R > cur_R:
                    cur_R = R
            else:
                if cur_L <= max_q:
                    diff[cur_L] += 1
                    end = cur_R + 1
                    if end > max_q + 1:
                        end = max_q + 1
                    diff[end] -= 1
                cur_L, cur_R = L, R

        if cur_L is not None and cur_L <= max_q:
            diff[cur_L] += 1
            end = cur_R + 1
            if end > max_q + 1:
                end = max_q + 1
            diff[end] -= 1

    for i in range(1, max_q + 1):
        diff[i] += diff[i - 1]

    return [n - diff[q] for q in queries]
