from typing import List

class Solution:
    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        total_subarrays = n * (n + 1) // 2
        k = (total_subarrays + 1) // 2

        def count_at_most(limit: int) -> int:
            freq = {}
            left = 0
            distinct = 0
            count = 0

            for right, num in enumerate(nums):
                if freq.get(num, 0) == 0:
                    distinct += 1
                freq[num] = freq.get(num, 0) + 1

                while distinct > limit:
                    old = nums[left]
                    freq[old] -= 1
                    if freq[old] == 0:
                        distinct -= 1
                    left += 1

                count += right - left + 1

            return count

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if count_at_most(mid) >= k:
                hi = mid
            else:
                lo = mid + 1

        return lo
