def maxLength(x: int, y: int, z: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(x: int, y: int, z: int, last: int) -> int:
        # last: 0 = none, 1 = AA, 2 = BB, 3 = AB
        best = 0
        if x > 0 and last != 1:
            best = max(best, 1 + dp(x - 1, y, z, 1))
        if y > 0 and (last == 0 or last == 1):
            best = max(best, 1 + dp(x, y - 1, z, 2))
        if z > 0 and last != 1:
            best = max(best, 1 + dp(x, y, z - 1, 3))
        return best

    return 2 * dp(x, y, z, 0)
