def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7
    max_n = max(zero, one)

    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (max_n + 1)
    invfact[max_n] = pow(fact[max_n], MOD - 2, MOD)
    for i in range(max_n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def C(n, k):
        if n < 0 or k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD

    def compositions(n):
        res = [0] * (n + 1)
        for k in range(1, n + 1):
            total = 0
            for t in range(k + 1):
                rem = n - t * limit - 1
                if rem < k - 1:
                    break
                term = C(k, t) * C(rem, k - 1) % MOD
                if t & 1:
                    total -= term
                else:
                    total += term
            res[k] = total % MOD
        return res

    zero_comps = compositions(zero)
    one_comps = compositions(one)

    ans = 0
    for a in range(1, zero + 1):
        if a - 1 <= one:
            ans = (ans + zero_comps[a] * one_comps[a - 1]) % MOD
        if a <= one:
            ans = (ans + 2 * zero_comps[a] * one_comps[a]) % MOD
        if a + 1 <= one:
            ans = (ans + zero_comps[a] * one_comps[a + 1]) % MOD

    return ans
