def isGood(nums):
    max_val = max(nums)
    # base[n] has n + 1 elements, where n is the maximum value
    if len(nums) != max_val + 1:
        return False
    # Count occurrences: 1..max_val-1 must appear exactly once, max_val exactly twice
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1
    for i in range(1, max_val):
        if count.get(i, 0) != 1:
            return False
    if count.get(max_val, 0) != 2:
        return False
    # Ensure no extra unexpected values exist
    return sum(count.values()) == max_val + 1
