        while p * p <= x:
            if x % p == 0:
                parity = 0
                while x % p == 0:
                    x //= p
                    parity ^= 1
                if parity:
                    squarefree *= p
            p += 1

        if x > 1:
            squarefree *= x

        groups[squarefree] = groups.get(squarefree, 0) + nums[i - 1]

    return max(groups.values())
