            zeros1 += 1
        else:
            sum1 += x

    sum2 = zeros2 = 0
    for x in nums2:
        if x == 0:
            zeros2 += 1
        else:
            sum2 += x

    min1 = sum1 + zeros1
    min2 = sum2 + zeros2

    if zeros1 == 0 and zeros2 == 0:
        return sum1 if sum1 == sum2 else -1
    elif zeros1 == 0:
        return sum1 if sum1 >= min2 else -1
    elif zeros2 == 0:
        return sum2 if sum2 >= min1 else -1
    else:
        return max(min1, min2)

