        if start == len(num_str):
            return current == target

        for end in range(start + 1, len(num_str) + 1):
            substring_value = int(num_str[start:end])
            if can_partition(num_str, target, end, current + substring_value):
                return True

        return False

    total = 0
    for i in range(1, n + 1):
