def maximumStrength(nums, k):
    NEG = -10**30
    coeff = [0] * (k + 1)
    for i in range(1, k + 1):
        w = k - i + 1
        coeff[i] = w if i % 2 == 1 else -w

    closed = [NEG] * (k + 1)
    open_ = [NEG] * (k + 1)
    closed[0] = 0

    for x in nums:
        new_closed = closed[:]
        new_open = [NEG] * (k + 1)

        for t in range(1, k + 1):
            val = coeff[t] * x

            # Start a new subarray t from a closed state.
            prev = closed[t - 1]
            if prev != NEG:
                cand = prev + val
                if cand > new_open[t]:
                    new_open[t] = cand
                if cand > new_closed[t]:
                    new_closed[t] = cand

            # Continue the currently open subarray t.
            cur = open_[t]
            if cur != NEG:
                cand = cur + val
                if cand > new_open[t]:
                    new_open[t] = cand
                if cand > new_closed[t]:
                    new_closed[t] = cand

        closed, open_ = new_closed, new_open

    return max(closed[k], open_[k])
