    arr = data[1:1 + n]

    zero_count = arr.count(0)
    positive_count = n - zero_count

    # Any pair containing a zero has product 0, which is a square.
    ans = zero_count * (zero_count - 1) // 2 + zero_count * positive_count

    max_a = max(arr) if arr else 0

    # Smallest prime factor sieve
    spf = list(range(max_a + 1))
    for i in range(2, int(max_a ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    freq = Counter()

    for a in arr:
        if a == 0:
            continue

        x = a
        kernel = 1

        while x > 1:
            prime = spf[x]
            parity = 0
            while x % prime == 0:
                x //= prime
                parity ^= 1
            if parity:
                kernel *= prime

        freq[kernel] += 1

    for c in freq.values():
        ans += c * (c - 1) // 2

    print(ans)

