def replaceQuestionMarks(s: str) -> str:
    f = [0] * 26
    q = 0

    for ch in s:
        if ch == '?':
            q += 1
        else:
            f[ord(ch) - ord('a')] += 1

    n = len(s)

    def needed(t: int) -> int:
        total = 0
        for c in range(26):
            if f[c] < t:
                total += t - f[c]
        return total

    lo, hi = 0, n + 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if needed(mid) <= q:
            lo = mid
        else:
            hi = mid - 1

    T = lo
    D = q - needed(T)

    b = [0] * 26
    extra_used = 0
    res = []

    for ch in s:
        if ch != '?':
            res.append(ch)
        else:
            for c in range(26):
                if f[c] > T:
                    continue

                old = f[c] + b[c]
                new = old + 1

                if new > T + 1:
                    continue

                if old == T and extra_used >= D:
                    continue

                b[c] += 1
                if old == T:
                    extra_used += 1

                res.append(chr(ord('a') + c))
                break

    return ''.join(res)
