def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    best_len = float('inf')

    # Sliding window to find the shortest beautiful substring length
    left = 0
    ones = 0
    for right in range(n):
        if s[right] == '1':
            ones += 1
        while ones > k:
            if s[left] == '1':
                ones -= 1
            left += 1
        if ones == k:
            # Trim leading zeros to get the shortest window for this right end
            while s[left] == '0':
                left += 1
            best_len = min(best_len, right - left + 1)

    if best_len == float('inf'):
        return ""

    # Collect all beautiful substrings of length best_len, return lexicographically smallest
    result = None
    for start in range(n - best_len + 1):
        sub = s[start:start + best_len]
        if sub.count('1') == k:
            if result is None or sub < result:
                result = sub

    return result if result is not None else ""
