def min_superstring(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def merge(s: str, t: str) -> str:
        for k in range(min(len(s), len(t)), -1, -1):
            if s.endswith(t[:k]):
                return s + t[k:]
        return s + t

    strings = list({a, b, c})

    filtered = []
    for i, s in enumerate(strings):
        if not any(i != j and s in t for j, t in enumerate(strings)):
            filtered.append(s)

    if not filtered:
        filtered = strings

    best = None
    for perm in permutations(filtered):
        cur = perm[0]
        for s in perm[1:]:
            cur = merge(cur, s)

        if best is None or len(cur) < len(best) or (len(cur) == len(best) and cur < best):
            best = cur

    return best
