    for a in range(max_start + 1):
        cnt = 0
        for k in range(M):
            if S[a + k] != T[k]:
                cnt += 1
        mismatch[a] = cnt
        if cnt == 0:
            queue.append(a)

    is_hash = [False] * N
    hash_count = 0
    head = 0

    # Activate all currently valid intervals greedily
    while head < len(queue):
        a = queue[head]
        head += 1

        for i in range(a, a + M):
            if not is_hash[i]:
                is_hash[i] = True
                hash_count += 1

                # Update all intervals that cover position i
                left = max(0, i - M + 1)
                right = min(i, max_start)

                for b in range(left, right + 1):
                    if mismatch[b] > 0:
                        if S[i] != T[i - b]:
                            mismatch[b] -= 1
                            if mismatch[b] == 0:
