def minimum_operations(x: int, y: int) -> int:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(a: int) -> int:
        if a <= y:
            return y - a

        ans = a - y

        if a >= 5:
            r = a % 5
            if r == 0:
                ans = min(ans, 1 + dp(a // 5))
            else:
                ans = min(ans, r + 1 + dp(a // 5))
                ans = min(ans, 5 - r + 1 + dp(a // 5 + 1))

        if a >= 11:
            r = a % 11
            if r == 0:
                ans = min(ans, 1 + dp(a // 11))
            else:
                ans = min(ans, r + 1 + dp(a // 11))
                ans = min(ans, 11 - r + 1 + dp(a // 11 + 1))

        return ans

