def find_products(queries):
    def count_bits_up_to(n):
        total = 0
        for k in range(n.bit_length()):
            block = 1 << (k + 1)
            half = 1 << k
            full, rem = divmod(n + 1, block)
            cnt = full * half
            if rem > half:
                cnt += rem - half
            total += cnt
        return total

    def sum_bit_exponents_up_to(n):
        total = 0
        for k in range(n.bit_length()):
            block = 1 << (k + 1)
            half = 1 << k
            full, rem = divmod(n + 1, block)
            cnt = full * half
            if rem > half:
                cnt += rem - half
            total += k * cnt
        return total

    def partial_bit_exponent_sum(n, take):
        total = 0
        for k in range(n.bit_length()):
            if take == 0:
                break
            if (n >> k) & 1:
                total += k
                take -= 1
        return total

    def prefix_exponent_sum(length):
        if length <= 0:
            return 0

        lo, hi = 0, length
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if count_bits_up_to(mid) <= length:
                lo = mid
            else:
                hi = mid - 1

        complete = lo
        included = count_bits_up_to(complete)
        remaining = length - included

        total = sum_bit_exponents_up_to(complete)
        if remaining:
            total += partial_bit_exponent_sum(complete + 1, remaining)

        return total

    answer = []
    for frm, to, mod in queries:
        exponent = prefix_exponent_sum(to + 1) - prefix_exponent_sum(frm)
        answer.append(pow(2, exponent, mod))

    return answer
