def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    valid = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                valid[i][j] = True

    dp = [[0] * n for _ in range(1 << n)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(1 << n):
        for last in range(n):
            cnt = dp[mask][last]
            if cnt == 0:
                continue

            for nxt in range(n):
                if not (mask & (1 << nxt)) and valid[last][nxt]:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + cnt) % MOD

    full_mask = (1 << n) - 1
    return sum(dp[full_mask]) % MOD
