from typing import List

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False

        limit = max(nums)

        # Smallest prime factor sieve
        spf = list(range(limit + 1))
        for i in range(2, int(limit ** 0.5) + 1):
            if spf[i] == i:
                for j in range(i * i, limit + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        parent = list(range(limit + 1))
        size = [1] * (limit + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        # Union all prime factors of each number together
        for x in nums:
            first = 0
            y = x
            while y > 1:
                p = spf[y]
                if first == 0:
                    first = p
                else:
                    union(first, p)
                while y % p == 0:
                    y //= p

        # Check whether all numbers belong to the same prime-factor component
        root = find(spf[nums[0]])
        for x in nums:
            if find(spf[x]) != root:
                return False

        return True
