def minimumOperations(s1: str, s2: str, s3: str) -> int:
    # Find the length of the longest common prefix of the three strings
    max_prefix = min(len(s1), len(s2), len(s3))
    common = 0
    for i in range(max_prefix):
        if s1[i] == s2[i] == s3[i]:
            common += 1
        else:
            break

    # If there is no common prefix, it's impossible to make them equal
    if common == 0:
        return -1

    # Each string must be truncated down to the common prefix length
    return (len(s1) - common) + (len(s2) - common) + (len(s3) - common)
