class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        m = len(s)
        base = limit + 1

        def count_leq(n: int) -> int:
            if n <= 0:
                return 0

            ns = str(n)
            if len(ns) < m:
                return 0

            total = 0

            # Count powerful integers with fewer digits than n.
            for length in range(m, len(ns)):
                p = length - m
                if p == 0:
                    total += 1
                else:
                    total += limit * (base ** (p - 1))

            p = len(ns) - m

            # Same length as s.
            if p == 0:
                return total + (1 if s <= ns else 0)

            prefix = ns[:p]
            suffix = ns[p:]

            less = 0
            equal_valid = True

            for i, ch in enumerate(prefix):
                d = ord(ch) - ord('0')
                lo = 1 if i == 0 else 0

                if d > lo:
                    choices = min(limit, d - 1) - lo + 1
                    if choices > 0:
                        less += choices * (base ** (p - i - 1))

                if d < lo or d > limit:
                    equal_valid = False
                    break

            if equal_valid and s <= suffix:
                less += 1

            return total + less

        return count_leq(finish) - count_leq(start - 1)
