    W = int(data[1])
    N = int(data[2])
    T = data[3]
    S = data[4:4 + H]

    mask = (1 << W) - 1
    land = []

    for row in S:
        bits = 0
        for j, ch in enumerate(row):
            if ch == '.':
                bits |= 1 << j
        land.append(bits)

    # A[r] is a bitmask of possible positions in row r after current moves.
    A = land[:]

    for ch in T:
        B = [0] * H

        if ch == 'L':
            for r in range(H):
                B[r] = (A[r] >> 1) & land[r]

        elif ch == 'R':
            for r in range(H):
                B[r] = ((A[r] << 1) & mask) & land[r]

        elif ch == 'U':
            for r in range(H - 1):
                B[r] = A[r + 1] & land[r]

        elif ch == 'D':
            for r in range(1, H):
                B[r] = A[r - 1] & land[r]

        A = B

    answer = sum(bits.bit_count() for bits in A)
    print(answer)

