def maxIncreasingGroups(usageLimits):
    usageLimits.sort()
    n = len(usageLimits)

    # Prefix sums of sorted usageLimits
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + usageLimits[i]

    # F[m] = sum(min(usageLimits[i], m))
    F = [0] * (n + 1)
    idx = 0
    for m in range(1, n + 1):
        while idx < n and usageLimits[idx] < m:
            idx += 1
        F[m] = prefix[idx] + (n - idx) * m

    def can_make(k):
        if k > n:
            return False
        for m in range(1, k + 1):
            # Sum of the largest m group sizes: k + (k-1) + ... + (k-m+1)
            needed = m * (2 * k - m + 1) // 2
            if F[m] < needed:
                return False
        return True

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_make(mid):
            lo = mid
        else:
            hi = mid - 1

    return lo
```

