def numberOfWays(s: str, t: str, k: int) -> int:
    MOD = 10**9 + 7
    n = len(s)

    # KMP prefix function for s to find its minimal circular period.
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    period = n - pi[-1]
    if n % period != 0:
        period = n

    # Number of distinct shifts that map s to a fixed rotation of s.
    m = n // period

    # Check whether t is a rotation of s.
    if s != t:
        pi_t = [0] * n
        for i in range(1, n):
            j = pi_t[i - 1]
            while j > 0 and t[i] != t[j]:
                j = pi_t[j - 1]
            if t[i] == t[j]:
                j += 1
            pi_t[i] = j

        j = 0
        found = False
        for i in range(2 * n - 1):
            ch = s[i] if i < n else s[i - n]
            while j > 0 and ch != t[j]:
                j = pi_t[j - 1]
            if ch == t[j]:
                j += 1
                if j == n:
                    found = True
                    break

        if not found:
            return 0

    inv_n = pow(n, MOD - 2, MOD)
    sign = 1 if k % 2 == 0 else MOD - 1

    # y = number of ways to end at any fixed non-zero shift.
    y = (pow(n - 1, k, MOD) - sign) * inv_n % MOD

    if s == t:
        return (m * y + sign) % MOD
    else:
        return (m * y) % MOD
```

